// animal_raca replacing them completely with the passed
// in related items, optionally inserting them as new records.
// Sets o.R.Anir's AnirEntidadeAnimals accordingly.
// Replaces o.R.AnirEntidadeAnimals with related.
// Sets related.R.Anir's AnirEntidadeAnimals accordingly.
func (o *AnimalRaca) SetAnirEntidadeAnimals(ctx context.Context, exec boil.ContextExecutor, insert bool, related ...*EntidadeAnimal) error {
	query := "update `entidade_animal` set `anir_id` = null where `anir_id` = ?"
	values := []interface{}{o.AnirID}
	if boil.IsDebug(ctx) {
		writer := boil.DebugWriterFrom(ctx)
		fmt.Fprintln(writer, query)
		fmt.Fprintln(writer, values)
	}
	_, err := exec.ExecContext(ctx, query, values...)
	if err != nil {
		return errors.Wrap(err, "failed to remove relationships before set")
	}

	if o.R != nil {
		for _, rel := range o.R.AnirEntidadeAnimals {
			queries.SetScanner(&rel.AnirID, nil)
			if rel.R == nil {
				continue
			}

			rel.R.Anir = nil
		}
		o.R.AnirEntidadeAnimals = nil
	}

	return o.AddAnirEntidadeAnimals(ctx, exec, insert, related...)
}

// RemoveAnirEntidadeAnimals relationships from objects passed in.
// Removes related items from R.AnirEntidadeAnimals (uses pointer comparison, removal does not keep order)
// Sets related.R.Anir.
func (o *AnimalRaca) RemoveAnirEntidadeAnimals(ctx context.Context, exec boil.ContextExecutor, related ...*EntidadeAnimal) error {
	if len(related) == 0 {
		return nil
	}

	var err error
	for _, rel := range related {
		queries.SetScanner(&rel.AnirID, nil)
		if rel.R != nil {
			rel.R.Anir = nil
		}
		if _, err = rel.Update(ctx, exec, boil.Whitelist("anir_id")); err != nil {
			return err
		}
	}
	if o.R == nil {
		return nil
	}

	for _, rel := range related {
		for i, ri := range o.R.AnirEntidadeAnimals {
			if rel != ri {
				continue
			}

			ln := len(o.R.AnirEntidadeAnimals)
			if ln > 1 && i < ln-1 {
				o.R.AnirEntidadeAnimals[i] = o.R.AnirEntidadeAnimals[ln-1]
			}
			o.R.AnirEntidadeAnimals = o.R.AnirEntidadeAnimals[:ln-1]
			break
		}
	}

	return nil
}

